fn match_path(segs: &[Seg], path: &str) -> Option<BTreeMap<String, String>> {
    let mut rest = path;
    let mut vars = BTreeMap::new();
    for seg in segs {
        rest = rest.strip_prefix('/')?;
        match seg {
            Seg::Lit(l) => {
                rest = rest.strip_prefix(l)?;
                if !(rest.is_empty() || rest.starts_with('/')) {
                    return None;
                }
            }
            Seg::Var(v) => {
                let end = rest.find('/').unwrap_or(rest.len());
                if end == 0 {
                    return None;
                }
                vars.insert(
                    v.to_string(),
                    roto_protocol::restxml::percent_decode_path(&rest[..end]),
                );
                rest = &rest[end..];
            }
            Seg::Greedy(v) => {
                if rest.is_empty() {
                    return None;
                }
                vars.insert(
                    v.to_string(),
                    roto_protocol::restxml::percent_decode_path(rest),
                );
                rest = "";
            }
        }
    }
    (rest.is_empty() || rest == "/").then_some(vars)
}

/// Finds the operation for a request and extracts its URI variables.
pub fn route(
    req: &RawRequest,
    q: &QueryParams,
) -> Option<(&'static str, BTreeMap<String, String>)> {
    ROUTES.iter().find_map(|r| {
        if r.method != req.method {
            return None;
        }
        if let Some(h) = r.header {
            req.header(h)?;
        }
        for (k, v) in r.query {
            match (q.get(k), v) {
                (None, _) => return None,
                (Some(have), Some(want)) if have != *want => return None,
                _ => {}
            }
        }
        match_path(r.segs, &req.path).map(|vars| (r.op, vars))
    })
}

